/**
 * ARRÊTER LA PRÉSENTATION SYNCHRONISÉE
 *
 * Cette macro termine la session partagée active et ferme le terminal partagé
 * pour les participants. Elle ne supprime ni Journal, ni page, ni configuration.
 * Aucune valeur n’est à modifier.
 */

// ── CONFIGURATION ─────────────────────────────────────────────
// Aucune : cette macro agit sur la présentation active.
// ──────────────────────────────────────────────────────────────

if (!game.user.isGM) return ui.notifications.error("Cette macro est réservée au MJ.");
const api = game.modules.get("retro-crt-terminal")?.api;
if (!api) return ui.notifications.error("Retro CRT Terminal n’est pas actif.");
if (!api.shared.state?.active) return ui.notifications.warn("Aucune présentation synchronisée n’est active.");

await api.shared.stop();
ui.notifications.info("Présentation synchronisée arrêtée.");
